import{_ as t,o as s,c as r,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Crimson/SeaStor OSD 2020-07-08","description":"","frontmatter":{"title":"Ceph Crimson/SeaStor OSD 2020-07-08","date":"2020-07-08T00:00:00.000Z","updated":"2020-07-09T00:00:00.000Z","tags":["Ceph","分布式存储","Crimson 存储引擎","RocksDB","测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-07-08.md","filePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-07-08.md","lastUpdated":1780459816000}'),n={name:"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-07-08.md"};function i(p,o,l,a,_,C){return s(),r("div",null,[...o[0]||(o[0]=[e("<p>本次会议主要讨论了Ceph存储系统的稳定性、性能优化、存储引擎开发及相关测试等方面的问题。</p><p><strong>关键细节</strong>：</p><ul><li><strong>Ceph存储系统稳定性测试</strong>：使用BB C locator进行压力测试，成功解决了由构建locator chip引起的崩溃问题。在CentOS 8环境下，通过基于total的环境将地址转换为堆栈回溯，并重复测试。</li><li><strong>RocksDB与Ceph集成问题</strong>：讨论了RocksDB在Ceph中的使用问题，特别是RocksDB创建的存储与Ceph存储池的兼容性问题。提出通过覆盖创建的符号来中断物理存储，并在创建时配置存储池的解决方案。</li><li><strong>Ceph存储地址对齐测试</strong>：讨论了非页面对齐地址的测试，确保测试案例涵盖非页面对齐的逻辑地址，并计划编写测试案例。</li><li><strong>Crimson存储引擎的开发</strong>：讨论了Crimson存储引擎的开发进展，包括回填和恢复功能的实现，强调了Crimson与经典OSD在事件调度和处理上的差异。</li></ul><p><strong>主要议题</strong>：</p><ul><li><strong>Ceph存储系统的稳定性与性能优化</strong>：通过压力测试和地址转换技术解决系统崩溃问题，优化RocksDB与Ceph的集成。</li><li><strong>Crimson存储引擎的功能开发与测试</strong>：详细讨论了Crimson引擎的回填和恢复功能的实现，强调了代码的可测试性和与经典OSD的兼容性。</li></ul><p><strong>决定事项</strong>：</p><ul><li>继续推进Crimson存储引擎的开发，确保其与经典OSD兼容并优化事件调度和处理机制。</li><li>编写和审查非页面对齐地址的测试案例，确保测试案例的全面性和准确性。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>继续进行Crimson存储引擎的开发和测试，完成回填和恢复功能的实现，并进行详细的测试以确保稳定性。</li><li>优化RocksDB与Ceph的集成，通过覆盖符号和配置存储池来解决兼容性问题。</li><li>编写和审查非页面对齐地址的测试案例，提交PR供社区审查。</li></ul><p>本次会议详细讨论了Ceph存储系统的多个关键问题，并制定了明确的后续行动计划，以确保系统的稳定性和性能优化。</p>",10)])])}const g=t(n,[["render",i]]);export{c as __pageData,g as default};
